          answerFa: "این فهرست احتمالاً به درس یا درس‌هایی درباره زمان یا متنی درباره رابطهٔ کسی با زمان مرتبط است. یک سازماندهی ممکن شامل جمع‌آوری واژه‌های ساعت در یک نقشهٔ واژگان یا دیاگرام حباب باشد (ساعت، مچ‌بند، عقربه‌ها، عقربهٔ دقیقه)؛ سپس می‌توان واژه‌های دیگر را بعداً اضافه کرد (عقربهٔ ساعت، صفحه/رویه، دیجیتال و غیره). «ساعت را بگو» و «چند ساعت است؟» می‌توانند فهرست جداگانه‌ای از «عبارات زمان» تشکیل دهند، به سایر عبارات نیز می‌توان اضافه کرد، مثلاً «وقت را دارید؟»، «ساعت من سریع/کند است» و غیره. خواب‌آلود و کاملاً بیدار را می‌توان به عنوان متضاد در نظر گرفت و برخی نکات در مورد کاربرد beneath و under مفید خواهد بود. این فهرست می‌تواند اطلاعاتی دربارهٔ ردهٔ واژگانی (word-class) نیز داشته باشد."
