          answerFa: "اسم: production, industry, export | فعل: produce, industrialise, export | صفت: productive, industrial, export | شخص: producer, industrialist, exporter. توجه کنید که تکیه‌کلمه در export (اسم یا صفت) با export (فعل) و exporter (شخص) متفاوت است، مثلاً Our export figures have increased; we exported 20% more goods last year."
