          answerFa: "پاسخ‌های ممکن. توجه: اکثر جملات در «انگلیسی واقعی» از استفاده از جفت واژه‌های هم‌آوا اجتناب می‌کنند، زیرا ممکن است گیج‌کننده باشند و اغلب طبیعی به نظر نمی‌رسند. | 1 آنها می‌خواهند عمویشان را امشب آنجا برای شام ببرند. | 2 این اولین باری است که ماشین امسال از گاراژ خارج شده است. | 3 بیایید اول با این تمرینات دستور زبان تمرین کنیم و بعد برخی تمرینات واژگان را انجام دهیم. | 4 دیدن یک آتش زیبا که در شومینه می‌سوزد، فوق‌العاده است. | 5 اینقدر ناله نکن، فقط به خاطر اینکه شراب تمام شده است. | 6 الآن ترمز بگیر یا آن اسباب‌بازی را در جاده می‌شکنی. | 7 این سایت باستان‌شناسی در غروب خورشید، منظره‌ای شگفت‌انگیز بود. | 8 بیایید دعا کنیم که هرگز قربانی افکار شرقی نشویم. | 9 اگرچه کمی خشخال بود، اما او را از اسب‌سواری برف منحرف نکرد. | 10 منظره زیبای پرتوهای ماه بازتاب‌یافته در دریاچه بسیار به روحیه او کمک کرد."
