          answerFa: "1 یک ژاکت پشمی. این یک بازی با واژه‌ها بر روی دو معنی ژاکت است – یک ژاکت پشمی و یک شخص یا حیوانی که می‌پرد. | 2 بیایید دام بازی کنیم. این یک بازی با واژه‌ها بر روی دو معنی دام است. یکی بازی است که با مهره‌های گرد و یک صفحه شطرنجی انجام می‌شود و دیگری یک جریان هواست مانند «یک باد terrible از زیر در می‌آید». | 3 او می‌خواست پرده‌ها را بکشد. این یک بازی با واژه‌ها بر روی دو معنی کشیدن است. اولی به معنای کشیدن نقاشی و دومی به معنای کشیدن است. | 4 چون پر از تاریخ است. این یک بازی با واژه‌ها بر روی دو معنی تاریخ است. یکی به سال‌هایی مانند 1066، 1892 اشاره دارد و دیگری به میوه شیرین درختی از نوع نخل یا به یک شب گذرانده شده با دو نفر (معمولاً عاشقانه) اشاره دارد. | 5 طبل بسیار خوب است. این یک بازی با واژه‌ها بر روی دو معنی کوبیدن است. یک طبل‌زن طبل را می‌زند. همچنین عبارتی وجود دارد، «بسیار خوب است» که به معنای «سخت بهتر کردن است» است."
